/**
 * Generates a private DSA key using OpenSSL commands.
 *
 * This function creates a temporary parameter file, generates DSA parameters,
 * and then uses them to create the private key. The temporary file is securely
 * created with mkstemp and cleaned up after use.
 *
 * @return A string containing the PEM-formatted private key or an empty string if an error occurs.
 */
std::string create_dsa_key() {
    // Create a unique temporary filename for DSA parameters
    char param_filename[] = "/tmp/dsakey_XXXXXX";
    int fd = mkstemp(param_filename);

    if (fd == -1) {
        return "";
    }

    close(fd);  // We don't need the file descriptor open

